"""finite_blocks.py - closure of the semigroup generated by the one-apex blocks with apex word of length <= L
(kind-pasteur-2026-11-11-S25; pre-registered addendum E).

Coordinates (A, W, d): A = H, W = o + e, d = o - e at the root.  A block with data (g, P, Q, n) acts by
    A' = g A + (Q + 1) W - [Q even] d,   W' = (P + 1) A + 2^n W,   d' = [P even] A - [n = 0] d,
starting from the virtual state (1, 0, 0).  A' >= W for every block, so states with W > X are dead.

usage: python finite_blocks.py K [Lmax]
"""
import sys
from itertools import product

import numpy as np
from numba import njit

from chain_semigroup import g_list


@njit(cache=True)
def insert(table, key):
    mask = table.shape[0] - 1
    h = (key * 0x9E3779B97F4A7C15) & 0x7FFFFFFFFFFFFFFF
    idx = h & mask
    while True:
        cur = table[idx]
        if cur == key:
            return False
        if cur == -1:
            table[idx] = key
            return True
        idx = (idx + 1) & mask


@njit(cache=True)
def closure(X, gg, p1, q1, qe, pe, n0, tn, hit, table, stK):
    ngen = gg.shape[0]
    cap = stK.shape[0]
    ns = 1
    stK[0] = (1 << 40)                      # virtual state (1, 0, 0)
    states = 0
    while ns > 0:
        ns -= 1
        kk = stK[ns]
        A = kk >> 40
        W = (kk >> 20) & 0xFFFFF
        d = kk & 0xFFFFF
        states += 1
        for c in range(ngen):
            A2 = gg[c] * A + q1[c] * W - qe[c] * d
            if A2 > X:
                continue
            hit[A2] = 1
            W2 = p1[c] * A + tn[c] * W
            if W2 > X:
                continue
            d2 = pe[c] * A - n0[c] * d
            key = (A2 << 40) | (W2 << 20) | d2
            if insert(table, key):
                if ns >= cap:
                    return -1
                stK[ns] = key
                ns += 1
    return states


def blocks(L, G):
    out = []
    for n in range(0, L + 1):
        for w in product((0, 1), repeat=n):
            P = 0
            for a in w:
                P = 2 * P + a
            Q = sum(1 << j for j, a in enumerate(w) if not a)
            out.append((G[P], P + 1, Q + 1, 1 - (Q & 1), 1 - (P & 1), 1 if n == 0 else 0, 1 << n))
    return out


def run(K, L):
    X = 1 << K
    G = g_list(1 << (L + 1))
    bl = blocks(L, G)
    arr = [np.array([b[i] for b in bl], dtype=np.int64) for i in range(7)]
    hit = np.zeros(X + 1, dtype=np.uint8)
    table = np.full(1 << 26, -1, dtype=np.int64)
    stK = np.zeros(1 << 25, dtype=np.int64)
    states = closure(X, arr[0], arr[1], arr[2], arr[3], arr[4], arr[5], arr[6], hit, table, stK)
    odd = np.arange(1, X + 1, 2)
    miss = odd[hit[odd] == 0]
    top = int(np.sum(miss >= X // 2))
    mid = int(np.sum(miss >= X // 8))
    print("L = %d (%d blocks), closure below 2^%d: %d live states; odd numbers missed: %d; in [2^%d, 2^%d): %d; in [2^%d, 2^%d): %d"
          % (L, len(bl), K, states, len(miss), K - 3, K, mid, K - 1, K, top))
    print("   first misses:", miss[:45].tolist())
    print("   last misses:", miss[-8:].tolist())
    sys.stdout.flush()


if __name__ == "__main__":
    K = int(sys.argv[1])
    Lmax = int(sys.argv[2]) if len(sys.argv) > 2 else 4
    for L in range(0, Lmax + 1):
        run(K, L)
